function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000 || v > 1000000)) return 'Each value is an integer between -10^6 and 10^6.';
  return null;
}

