    const n = int(900, 1000);
    const bias = rand() < 0.5 ? 0 : (rand() < 0.5 ? 1 : -1) * 1000000;
    return [Array.from({ length: n }, () => bias !== 0 && rand() < 0.8 ? bias : int(-1000000, 1000000))];
